//! The shell's half of the Rust ↔ TypeScript contract (`emudome_core::contract`): the DTOs of
//! the commands and events defined here, generated into `app/src/generated/app/`. The core's
//! types they use are generated by the core's own test, one folder up.

use emudome_core::contract::{check_generated, generated_dir, Generated, BLESS};

/// The shell's files: those under `app/`.
fn app_owns(path: &str) -> bool {
    path.starts_with("app/")
}

fn generate() -> Result<Generated, String> {
    let mut g = Generated::new();
    g.ts::<crate::VideoMode>()?;
    g.ts::<crate::commands::SlotDto>()?;
    g.ts::<crate::game::GameInfo>()?;
    g.ts::<crate::commands::StatsDto>()?;
    g.ts::<crate::commands::PointerArea>()?;
    g.ts::<crate::bios::BiosRow>()?;
    g.ts::<crate::hotkeys::HotkeyEvent>()?;
    g.ts::<crate::core_settings::CoreRestart<'static>>()?;
    g.ts::<crate::library::LibraryDto>()?;
    g.ts::<crate::library::ScanEvent>()?;
    g.ts::<crate::migration::Status>()?;
    g.ts::<crate::saves::SummaryDto>()?;
    g.ts::<crate::saves::GameSavesDto>()?;
    g.ts::<crate::saves::ImportDto>()?;
    g.ts::<crate::saves::ExportWhat>()?;
    g.ts::<crate::saves::FolderSavesDto>()?;
    g.ts::<crate::settings::Changed<'static>>()?;
    g.ts::<crate::theme::Theme>()?;
    g.ts::<crate::pads::PadInfo>()?;
    g.ts::<crate::pads::PadStates>()?;
    g.ts::<crate::pads::ControlsBindings>()?;
    Ok(g)
}

#[test]
fn contract_generated_files_are_up_to_date() {
    let generated = generate().unwrap();
    let dir = generated_dir(env!("CARGO_MANIFEST_DIR"));
    let regenerate = format!("{BLESS}=1 cargo test -p emudome contract");
    if let Err(e) = check_generated(&dir, &generated, app_owns, &regenerate) {
        panic!("{e}");
    }
}
